import { dataUrl } from "../lib";

type Page = "atlas" | "site-weather";

// Pages still generated by the Python scripts are linked relative to docs/app/.
const LINKS: [label: string, href: string, page?: Page][] = [
  ["Atlas", "#/atlas", "atlas"],
  ["3D model", dataUrl("3d.html")],
  ["Stories", dataUrl("stories.html")],
  ["Day vs night", dataUrl("daynight.html")],
  ["Meteogram", dataUrl("meteogram.html")],
  ["Site weather", "#/site-weather", "site-weather"],
  ["Map", dataUrl("site-weather/map.html")],
  ["Share today", dataUrl("site-weather/share.html")],
  ["Figures", dataUrl("gallery.html")],
  ["Code", "https://github.com/gavacharles/kampala-heat-atlas"],
];

export function SiteNav({ current }: { current: Page }) {
  return (
    <nav className="nav">
      {LINKS.map(([label, href, page]) => (
        <a key={label} href={href} aria-current={page === current ? "page" : undefined}>{label}</a>
      ))}
    </nav>
  );
}
